summary:
bash: node -e "
const fs = require('fs');
const content = fs.readFileSync('my_website/.github/workflows/deploy.yml', 'utf8');
// Basic YAML validation: check for tab characters (invalid in YAML)
if (/\t/.test(content)) { console.log('FAIL: tabs found'); process.exit(1); }
// Check indentation is consistent (spaces only, no mixed tabs/spaces)
const lines = content.split('\n');
let ok = true;
for (let i = 0; i < lines.length; i++) {
  const line = lines[i];
  if (line && /^[ \t]+/.test(line)) {
    const spaces = line.match(/^[ ]+/);
    if (spaces && spaces[0].length !== line.match(/^[ \t]+/)[0].length) {
      console.log('FAIL: mixed tabs/spaces on line ' + (i+1));
      ok = false;
    }
  }
}
if (ok) console.log('YAML indentation looks valid (no tabs, consistent spaces)');
" 2>&1

